<?php
declare(strict_types=1);
session_start();
$dbFile = __DIR__ . '/banshree.sqlite';
try {
  $db = new PDO('sqlite:' . $dbFile);
  $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
  $db->exec("CREATE TABLE IF NOT EXISTS pickup_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    address TEXT NOT NULL,
    area TEXT,
    pickup_date TEXT,
    pickup_time TEXT,
    items_json TEXT NOT NULL,
    notes TEXT,
    status TEXT NOT NULL DEFAULT 'new',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )");
} catch (Throwable $e) {
  http_response_code(500);
  exit('SQLite is required on this PHP hosting. Enable PDO_SQLite / SQLite3.');
}

$adminPassword = getenv('BANSHREE_ADMIN_PASSWORD') ?: 'banshree2026';
$action = $_POST['action'] ?? '';

if ($action === 'admin_login') {
  if (hash_equals($adminPassword, (string)($_POST['password'] ?? ''))) {
    $_SESSION['banshree_admin'] = true;
  }
  header('Location: ?admin=1'); exit;
}
if ($action === 'admin_logout') { unset($_SESSION['banshree_admin']); header('Location: ?admin=1'); exit; }

if ($action === 'create_request') {
  header('Content-Type: application/json; charset=utf-8');
  $items = json_decode((string)($_POST['items'] ?? '[]'), true);
  if (!is_array($items) || !$items) { echo json_encode(['ok'=>false,'error'=>'Add at least one item.']); exit; }
  $name = trim((string)($_POST['name'] ?? ''));
  $phone = trim((string)($_POST['phone'] ?? ''));
  $address = trim((string)($_POST['address'] ?? ''));
  if ($name === '' || $phone === '' || $address === '') { echo json_encode(['ok'=>false,'error'=>'Name, phone and address are required.']); exit; }
  $stmt = $db->prepare('INSERT INTO pickup_requests (name,phone,address,area,pickup_date,pickup_time,items_json,notes) VALUES (?,?,?,?,?,?,?,?)');
  $stmt->execute([$name,$phone,$address,trim((string)($_POST['area'] ?? '')),trim((string)($_POST['pickup_date'] ?? '')),trim((string)($_POST['pickup_time'] ?? '')),json_encode($items, JSON_UNESCAPED_UNICODE),trim((string)($_POST['notes'] ?? ''))]);
  echo json_encode(['ok'=>true,'id'=>(int)$db->lastInsertId()]); exit;
}

if ($action === 'status' && !empty($_SESSION['banshree_admin'])) {
  $id=(int)($_POST['id']??0); $status=(string)($_POST['status']??'new');
  if (in_array($status,['new','contacted','scheduled','picked_up','cancelled'],true)) {
    $s=$db->prepare('UPDATE pickup_requests SET status=? WHERE id=?'); $s->execute([$status,$id]);
  }
  header('Location: ?admin=1'); exit;
}
if ($action === 'delete' && !empty($_SESSION['banshree_admin'])) {
  $s=$db->prepare('DELETE FROM pickup_requests WHERE id=?'); $s->execute([(int)($_POST['id']??0)]);
  header('Location: ?admin=1'); exit;
}

$admin = isset($_GET['admin']);
$requests=[];
if ($admin && !empty($_SESSION['banshree_admin'])) {
  $requests=$db->query('SELECT * FROM pickup_requests ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);
}
function h(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
