em-row{border:1px solid var(--line);padding:12px;display:flex;justify-content:space-between;gap:10px;font-size:13px}.remove{border:0;background:none;color:#a44}.notice{font-size:12px;color:var(--muted);line-height:1.6}.success{display:none;border:1px solid #9bb59d;background:#eef6ee;padding:15px;margin-top:15px}.admin{padding-top:60px}.admin-login{max-width:500px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{border-bottom:1px solid var(--line);padding:13px;text-align:left;vertical-align:top}.status{padding:5px 7px;border:1px solid var(--line);font-size:10px;text-transform:uppercase}.admin-actions{display:flex;gap:7px;align-items:center}.admin-actions select{padding:7px}.footer{padding:40px 0;border-top:1px solid var(--line);font-size:12px;color:var(--muted);display:flex;justify-content:space-between}.admin-link{font-size:11px;color:var(--muted)}@media(max-width:900px){.nav{display:none}.hero,.pickup-grid,.form-layout,.section-head{grid-template-columns:1fr}.hero{padding:45px 0}.hero-img{height:480px}.cards{grid-template-columns:1fr 1fr}.fields{grid-template-columns:1fr}.topbar{font-size:9px}}@media(max-width:560px){.wrap{width:min(100% - 24px,1240px)}h1{font-size:55px}.cards{grid-template-columns:1fr}.hero-img{height:390px}section{padding:75px 0}.header{height:68px}.brand small{font-size:8px}}
