ethod="post" onsubmit="return confirm('Delete this request?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><button class="btn" style="padding:7px 10px">Delete</button></form></div></td></tr><?php endforeach; if(!$requests): ?><tr><td colspan="7">No pickup requests yet.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
</main><footer class="footer wrap"><span>© <?=date('Y')?> Banshree Old Clothes Buyer Mumbai</span><a class="admin-link" href="?admin=1">Admin</a></footer>
<script>
gsap.registerPlugin(ScrollTrigger);
gsap.from('.hero-copy > *',{y:35,opacity:0,duration:.8,stagger:.1,ease:'power3.out'});gsap.from('.hero-img',{clipPath:'inset(0 0 100% 0)',duration:1.1,ease:'power3.inOut'});gsap.utils.toArray('.card').forEach((el,i)=>gsap.from(el,{scrollTrigger:{trigger:el,start:'top 85%'},y:50,opacity:0,duration:.7,delay:i*.05,ease:'power3.out'}));gsap.utils.toArray('.step').forEach(el=>gsap.from(el,{scrollTrigger:{trigger:el,start:'top 90%'},x:35,opacity:0,duration:.7,ease:'power3.out'}));gsap.utils.toArray('.panel').forEach(el=>gsap.from(el,{scrollTrigger:{trigger:el,start:'top 88%'},y:35,opacity:0,duration:.7,ease:'power3.out'}));
const items=[];const itemsEl=document.getElementById('items');function renderItems(){itemsEl.innerHTML=items.length?items.map((x,i)=>`<div class="item-row"><span><b>${x.category}</b> × ${x.quantity}${x.note?`<br><small>${x.note}</small>`:''}</span><button type="button" class="remove" onclick="items.splice(${i},1);renderItems()">Remove</button></div>`).join(''):'<div class="notice">No items added yet.</div>';}document.getElementById('addItem')?.addEventListener('click',()=>{const category=document.getElementById('cat').value,quantity=Math.max(1,parseInt(document.getElementById('qty').value||'1')),note=document.getElementById('itemnote').value.trim();items.push({category,quantity,note});document.getElementById('itemnote').value='';renderItems();});document.getElementById('pickupForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!items.length){alert('Please add at least one item.');return}const fd=new FormData(e.target);fd.append('action','create_request');fd.append('items',JSON.stringify(items));const r=await fetch('',{method:'POST',body:fd});const data=await r.json();if(data.ok){document.getElementById('success').style.display='block';document.getElementById('success').textContent='Pickup request #'+data.id+' submitted successfully. Admin can now see it.';e.target.reset();items.length=0;renderItems();gsap.from('#success',{y:10,opacity:0,duration:.4});}else alert(data.error||'Could not submit request.');});
</script>
</body></html>
